import React from "react";
import { BrowserRouter, Routes, Route, Link } from "react-router-dom";
import MenuPage from "./pages/MenuPage";
import OrderPage from "./pages/OrderPage";
import KitchenDashboard from "./pages/KitchenDashboard";
import WaiterDashboard from "./pages/WaiterDashboard";
import ReservationPage from "./pages/ReservationPage";
import AdminDashboard from "./pages/AdminDashboard";

function App() {
  return (
    <BrowserRouter>
      <header style={{ background: "#4a148c", padding: "15px" }}>
        <nav style={{ display: "flex", gap: "20px", color: "#fff" }}>
          <Link to="/" style={{ color: "#fff" }}>Menu</Link>
          <Link to="/order" style={{ color: "#fff" }}>Order</Link>
          <Link to="/kitchen" style={{ color: "#fff" }}>Kitchen</Link>
          <Link to="/waiter" style={{ color: "#fff" }}>Waiter</Link>
          <Link to="/reservation" style={{ color: "#fff" }}>Reservation</Link>
          <Link to="/admin" style={{ color: "#fff" }}>Admin</Link>
        </nav>
      </header>

      <main style={{ padding: "20px" }}>
        <Routes>
          <Route path="/" element={<MenuPage />} />
          <Route path="/order" element={<OrderPage />} />
          <Route path="/kitchen" element={<KitchenDashboard />} />
          <Route path="/waiter" element={<WaiterDashboard />} />
          <Route path="/reservation" element={<ReservationPage />} />
          <Route path="/admin" element={<AdminDashboard />} />
        </Routes>
      </main>
    </BrowserRouter>
  );
}

export default App;
